
CREATE TABLE competencia (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, nombre VARCHAR(180) NOT NULL, clave VARCHAR(180) NOT NULL UNIQUE, estado VARCHAR(20) NOT NULL CHECK (estado IN ('ACTIVO','INACTIVO')));
CREATE TABLE idioma (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, nombre VARCHAR(180) NOT NULL, clave VARCHAR(180) NOT NULL UNIQUE, estado VARCHAR(20) NOT NULL CHECK (estado IN ('ACTIVO','INACTIVO')));
CREATE TABLE puesto (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, nombre VARCHAR(180) NOT NULL, clave VARCHAR(180) NOT NULL UNIQUE, estado VARCHAR(20) NOT NULL CHECK (estado IN ('ACTIVO','INACTIVO')), riesgo VARCHAR(20) NOT NULL CHECK (riesgo IN ('BAJO','MEDIO','ALTO')), salario_minimo NUMERIC(14,2) NOT NULL CHECK(salario_minimo >= 0), salario_maximo NUMERIC(14,2) NOT NULL CHECK(salario_maximo > 0 AND salario_maximo >= salario_minimo));
CREATE TABLE capacitacion (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, nombre VARCHAR(180) NOT NULL, clave VARCHAR(180) NOT NULL UNIQUE, estado VARCHAR(20) NOT NULL CHECK (estado IN ('ACTIVO','INACTIVO')), nivel VARCHAR(20) NOT NULL CHECK (nivel IN ('GRADO','POST_GRADO','MAESTRIA','DOCTORADO','TECNICO','GESTION')), fecha_desde DATE NOT NULL, fecha_hasta DATE, institucion VARCHAR(180) NOT NULL, CHECK(fecha_hasta IS NULL OR fecha_hasta >= fecha_desde));
CREATE TABLE candidato (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, cedula VARCHAR(11) NOT NULL UNIQUE, nombre VARCHAR(100) NOT NULL, apellidos VARCHAR(100) NOT NULL, email VARCHAR(180) NOT NULL, telefono VARCHAR(30), puesto_id BIGINT NOT NULL REFERENCES puesto(id), departamento VARCHAR(100) NOT NULL, salario_aspirado NUMERIC(14,2) NOT NULL CHECK(salario_aspirado >= 0), recomendado_por VARCHAR(180), fecha_registro TIMESTAMP NOT NULL, estado VARCHAR(30) NOT NULL CHECK(estado IN ('REGISTRADO','EN_EVALUACION','PRESELECCIONADO','RECHAZADO','CONTRATADO')));
CREATE TABLE candidato_competencia (candidato_id BIGINT NOT NULL REFERENCES candidato(id), competencia_id BIGINT NOT NULL REFERENCES competencia(id), PRIMARY KEY(candidato_id,competencia_id));
CREATE TABLE candidato_capacitacion (candidato_id BIGINT NOT NULL REFERENCES candidato(id), capacitacion_id BIGINT NOT NULL REFERENCES capacitacion(id), PRIMARY KEY(candidato_id,capacitacion_id));
CREATE TABLE candidato_idioma (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, candidato_id BIGINT NOT NULL REFERENCES candidato(id), idioma_id BIGINT NOT NULL REFERENCES idioma(id), nivel VARCHAR(20) NOT NULL CHECK(nivel IN ('BASICO','INTERMEDIO','AVANZADO','NATIVO')), UNIQUE(candidato_id,idioma_id));
CREATE TABLE experiencia_laboral (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, candidato_id BIGINT NOT NULL REFERENCES candidato(id), empresa VARCHAR(180) NOT NULL, puesto_ocupado VARCHAR(180) NOT NULL, fecha_desde DATE NOT NULL, fecha_hasta DATE, salario NUMERIC(14,2) NOT NULL CHECK(salario >= 0), CHECK(fecha_hasta IS NULL OR fecha_hasta >= fecha_desde));
CREATE TABLE empleado (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, candidato_id BIGINT NOT NULL UNIQUE REFERENCES candidato(id), cedula VARCHAR(11) NOT NULL UNIQUE, nombre VARCHAR(210) NOT NULL, fecha_ingreso DATE NOT NULL, departamento VARCHAR(100) NOT NULL, puesto_id BIGINT NOT NULL REFERENCES puesto(id), salario_mensual NUMERIC(14,2) NOT NULL CHECK(salario_mensual > 0), estado VARCHAR(20) NOT NULL CHECK(estado IN ('ACTIVO','INACTIVO')));
CREATE INDEX idx_candidato_puesto ON candidato(puesto_id);
CREATE INDEX idx_candidato_estado ON candidato(estado);
CREATE INDEX idx_candidato_registro ON candidato(fecha_registro);
CREATE INDEX idx_candidato_departamento ON candidato(departamento);
CREATE INDEX idx_competencia_candidato ON candidato_competencia(competencia_id);
CREATE INDEX idx_capacitacion_candidato ON candidato_capacitacion(capacitacion_id);
CREATE INDEX idx_idioma_candidato ON candidato_idioma(idioma_id);
CREATE INDEX idx_experiencia_candidato ON experiencia_laboral(candidato_id);
CREATE INDEX idx_empleado_ingreso ON empleado(fecha_ingreso);
CREATE INDEX idx_empleado_puesto ON empleado(puesto_id);
CREATE INDEX idx_empleado_departamento ON empleado(departamento);

